// Restore must commit the new version and discard live edits together, or do neither.
// Run: node scripts/restore-test.ts
// A real HTTP/WebSocket server, email sign-in and an isolated database. The generated byte
// payloads exercise storage, not the drawing parser; no sample drawings are needed.

import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { once } from "node:events";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { WebSocket } from "ws";
import type { CloudFile, ServerMessage, WireOp } from "../../web/src/platform/protocol.ts";

const PORT = 20000 + Math.floor(Math.random() * 1000);
const BASE = `http://localhost:${PORT}`;
const data = mkdtempSync(join(tmpdir(), "rodeo-restore-"));
const original = new Uint8Array(3000).fill(7);
const current = new Uint8Array(4000).fill(8);
let log = "";
let cookie = "";
let db: DatabaseSync | undefined;
const sockets: WebSocket[] = [];
const server = spawn(process.execPath, ["src/index.ts"], {
  cwd: join(import.meta.dirname, ".."),
  env: {
    ...process.env, NODE_ENV: "development", PORT: String(PORT), DATA_DIR: data,
    PUBLIC_URL: BASE, SMTP_URL: "", FREE_BYTES: "11000", FREE_FILES: "30", FREE_VERSIONS: "100",
  },
  stdio: ["ignore", "pipe", "pipe"],
});
server.stdout.on("data", (d: Buffer) => (log += d.toString()));
server.stderr.on("data", (d: Buffer) => (log += d.toString()));
const exited = once(server, "exit");

async function until(check: () => boolean, what: string): Promise<void> {
  const end = Date.now() + 10_000;
  while (Date.now() < end) {
    if (check()) return;
    await new Promise((r) => setTimeout(r, 20));
  }
  throw new Error(`timed out waiting for ${what}\n${log}`);
}

function call(method: string, path: string, body?: BodyInit, headers: Record<string, string> = {}): Promise<Response> {
  return fetch(`${BASE}${path}`, {
    method, body, redirect: "manual",
    headers: { Cookie: cookie, "X-Requested-With": "openvwx", ...headers },
  });
}

async function fileResponse(res: Response, status = 200): Promise<CloudFile> {
  assert.equal(res.status, status, await res.clone().text());
  return ((await res.json()) as { file: CloudFile }).file;
}

async function create(bytes: Uint8Array): Promise<CloudFile> {
  return fileResponse(await call("POST", "/api/files", new Blob([bytes as Uint8Array<ArrayBuffer>]), {
    "Content-Type": "application/octet-stream", "X-File-Name": "restore-test.vwx",
  }), 201);
}

interface Conn {
  ws: WebSocket;
  seen: ServerMessage[];
}

async function connect(file: CloudFile): Promise<Conn> {
  const ws = new WebSocket(`ws://localhost:${PORT}/api/collab/${file.id}`, { headers: { Cookie: cookie, Origin: BASE } });
  sockets.push(ws);
  const seen: ServerMessage[] = [];
  ws.on("message", (d) => seen.push(JSON.parse(d.toString()) as ServerMessage));
  await once(ws, "open");
  ws.send(JSON.stringify({ t: "hello", versionId: file.headVersionId }));
  await until(() => seen.some((m) => m.t === "welcome"), "welcome");
  return { ws, seen };
}

async function leave(c: Conn): Promise<void> {
  const closed = once(c.ws, "close");
  c.ws.close();
  await closed;
}

// A ping is a barrier: any earlier reload on this socket would arrive before its pong.
async function flush(c: Conn): Promise<void> {
  const before = c.seen.filter((m) => m.t === "pong").length;
  c.ws.send(JSON.stringify({ t: "ping" }));
  await until(() => c.seen.filter((m) => m.t === "pong").length > before, "pong");
}

const edit: WireOp = { start: 0, del: 0, kind: "objects", ids: ["test-object"], add: [Buffer.from([1, 2, 3, 4]).toString("base64")] };

async function change(c: Conn, base: number): Promise<void> {
  c.ws.send(JSON.stringify({ t: "op", id: base + 1, base, op: edit }));
  await until(() => c.seen.some((m) => m.t === "ack" && m.seq === base + 1), "acknowledged edit");
}

function snapshot(fileId: string): unknown {
  return {
    file: db!.prepare("SELECT * FROM files WHERE id = ?").get(fileId),
    versions: db!.prepare("SELECT * FROM versions WHERE file_id = ? ORDER BY rowid").all(fileId),
    room: db!.prepare("SELECT * FROM collab_rooms WHERE file_id = ?").get(fileId),
    ops: db!.prepare("SELECT * FROM collab_ops WHERE file_id = ? ORDER BY seq").all(fileId),
  };
}

function welcome(c: Conn): Extract<ServerMessage, { t: "welcome" }> {
  return c.seen.find((m) => m.t === "welcome")!;
}

type Failure = "quota" | "version" | "log" | "header" | "commit";

async function check(failure: Failure, joined: boolean): Promise<void> {
  const first = await create(original);
  const file = await fileResponse(await call("PUT", `/api/files/${first.id}/content`, current, { "X-Base-Version": first.headVersionId }));
  const a = await connect(file);
  const b = await connect(file);
  await change(a, 0);
  await until(() => b.seen.some((m) => m.t === "op" && m.seq === 1), "the other editor's change");
  if (!joined) {
    await leave(b);
    await until(() => a.seen.some((m) => m.t === "leave"), "the other editor leaving");
    await leave(a); // last client leaves: the room is evicted from memory
  }

  let filler: CloudFile | undefined;
  if (failure === "quota") filler = await create(new Uint8Array(2000).fill(9));
  else {
    const at = {
      version: "BEFORE INSERT ON versions",
      log: "AFTER DELETE ON collab_ops",
      header: "AFTER UPDATE ON collab_rooms",
      commit: "AFTER UPDATE ON collab_rooms",
    }[failure];
    // The deferred foreign key fails at COMMIT, after all version/log statements succeeded.
    const action = failure === "commit"
      ? "INSERT INTO restore_commit_failure VALUES ('missing-parent');"
      : "SELECT RAISE(ABORT, 'injected restore failure');";
    db!.exec(`CREATE TRIGGER restore_failure ${at} BEGIN ${action} END`);
  }
  const before = snapshot(file.id);
  try {
    const res = await call("POST", `/api/files/${file.id}/versions/${first.headVersionId}/restore`);
    assert.equal(res.status, failure === "quota" ? 409 : 500, await res.clone().text());
    if (failure === "quota") assert.equal(((await res.json()) as { code: string }).code, "limit");
    assert.deepEqual(snapshot(file.id), before, `${failure}: head, versions and persistent collaboration must be unchanged`);
    if (joined) {
      for (const c of [a, b]) {
        await flush(c);
        assert.equal(c.seen.filter((m) => m.t === "reload").length, 0, "a failed restore must not reload editors");
      }
    }
    const late = await connect(file);
    assert.equal(welcome(late).seq, 1);
    assert.deepEqual(welcome(late).ops, [{ seq: 1, op: edit }], "catch-up must retain the acknowledged edit");
    await leave(late);
  } finally {
    if (filler) assert.equal((await call("DELETE", `/api/files/${filler.id}`)).status, 204);
    else db!.exec("DROP TRIGGER restore_failure");
  }

  // Existing clients can still edit after refusal. An unloaded room stays unloaded for retry.
  const seq = joined ? 2 : 1;
  if (joined) {
    await change(a, 1);
    await until(() => b.seen.some((m) => m.t === "op" && m.seq === 2), "continued editing");
  }
  const restored = await fileResponse(await call("POST", `/api/files/${file.id}/versions/${first.headVersionId}/restore`));
  assert.notEqual(restored.headVersionId, file.headVersionId);
  assert.notEqual(restored.headVersionId, first.headVersionId, "restore adds a version");
  const content = await call("GET", `/api/files/${file.id}/content`);
  assert.equal(content.headers.get("x-collab-seq"), String(seq));
  assert.deepEqual(new Uint8Array(await content.arrayBuffer()), original);
  assert.equal(db!.prepare("SELECT COUNT(*) AS n FROM versions WHERE file_id = ?").get(file.id)!.n, 3);
  assert.equal(db!.prepare("SELECT COUNT(*) AS n FROM collab_ops WHERE file_id = ?").get(file.id)!.n, 0);
  const room = db!.prepare("SELECT last_seq, saved_seq, first_unsaved_at FROM collab_rooms WHERE file_id = ?").get(file.id)!;
  assert.deepEqual({ ...room }, { last_seq: seq, saved_seq: seq, first_unsaved_at: null });
  if (joined) {
    for (const c of [a, b]) {
      await flush(c);
      assert.equal(c.seen.filter((m) => m.t === "reload").length, 1, "success reloads each editor exactly once");
      c.ws.send(JSON.stringify({ t: "hello", versionId: restored.headVersionId }));
      await until(() => c.seen.filter((m) => m.t === "welcome").length === 2, "rejoining the restored version");
      const again = c.seen.filter((m) => m.t === "welcome").at(-1)!;
      assert.equal(again.seq, seq);
      assert.deepEqual(again.ops, []);
    }
    await change(a, seq);
    await until(() => b.seen.some((m) => m.t === "op" && m.seq === seq + 1), "editing after restore");
    await leave(b);
    await leave(a);
  } else {
    const fresh = await connect(restored);
    assert.equal(welcome(fresh).seq, seq);
    assert.deepEqual(welcome(fresh).ops, []);
    await change(fresh, seq);
    await leave(fresh);
  }
  assert.equal((await call("DELETE", `/api/files/${file.id}`)).status, 204);
  console.log(`restore-test: ${failure}, ${joined ? "connected" : "unloaded"} room passed`);
}

try {
  await until(() => log.includes("listening"), "the server");
  db = new DatabaseSync(join(data, "openvwx.db"));
  db.exec(`
    PRAGMA busy_timeout = 5000;
    CREATE TABLE restore_parent (id TEXT PRIMARY KEY);
    CREATE TABLE restore_commit_failure (parent TEXT REFERENCES restore_parent(id) DEFERRABLE INITIALLY DEFERRED);
  `);
  const login = await call("POST", "/api/auth/email", JSON.stringify({ email: "restore-test@example.com" }), { "Content-Type": "application/json" });
  assert.equal(login.status, 200);
  await until(() => /callback\?token=[\w-]+/.test(log), "the sign-in link");
  cookie = ((await call("GET", /(\/api\/auth\/email\/callback\?token=[\w-]+)/.exec(log)![1])).headers.get("set-cookie") ?? "").split(";")[0];
  assert.ok(cookie);
  for (const joined of [true, false]) {
    for (const failure of ["quota", "version", "log", "header", "commit"] as const) await check(failure, joined);
  }
  // A drawing with no collaboration state must also get its restored version.
  const plain = await create(original);
  const restored = await fileResponse(await call("POST", `/api/files/${plain.id}/versions/${plain.headVersionId}/restore`));
  assert.notEqual(restored.headVersionId, plain.headVersionId);
  const fresh = await connect(restored);
  assert.equal(welcome(fresh).seq, 0);
  assert.deepEqual(welcome(fresh).ops, []);
  await leave(fresh);
  console.log("restore-test: all passed (including a drawing with no collaboration state)");
} finally {
  for (const ws of sockets) if (ws.readyState !== WebSocket.CLOSED) ws.terminate();
  server.kill();
  await exited;
  db?.close();
  rmSync(data, { recursive: true, force: true });
}
